package com.agriconnect.rescue;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import java.math.BigDecimal;import java.util.Map;import org.h2.jdbcx.JdbcDataSource;import org.junit.jupiter.api.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;
class RescueWorkflowTest{private RescueRegistrationController controller;private CropClient crop;@BeforeEach void setup(){JdbcDataSource ds=new JdbcDataSource();ds.setURL("jdbc:h2:mem:rescue;MODE=PostgreSQL;DB_CLOSE_DELAY=-1");JdbcTemplate j=new JdbcTemplate(ds);j.execute("drop all objects");j.execute("create table rescue_points(id bigint generated by default as identity primary key,name varchar(255),province varchar(100),address_detail varchar(255),status varchar(20))");j.execute("create table rescue_registrations(id bigint generated by default as identity primary key,crop_batch_id bigint,farmer_id bigint,rescue_point_id bigint,admin_id bigint,quantity_snapshot numeric(12,2),status varchar(20),submitted_at timestamp with time zone default current_timestamp,reviewed_at timestamp with time zone)");j.execute("create table rescue_status_history(id bigint generated by default as identity primary key,registration_id bigint,from_status varchar(20),to_status varchar(20),changed_by bigint,changed_at timestamp with time zone default current_timestamp)");j.update("insert into rescue_points(name,province,address_detail,status)values('Point','HCM','Address','ACTIVE')");crop=mock(CropClient.class);controller=new RescueRegistrationController(JdbcClient.create(ds),crop);auth(7);}@AfterEach void clear(){SecurityContextHolder.clearContext();}
@Test void rejectsAnotherFarmersBatch(){when(crop.batch(10)).thenReturn(Map.of("farmerId",99,"status","available","currentQuantity",BigDecimal.TEN));assertThatThrownBy(()->controller.create(Map.of("batchId",10,"rescuePointId",1))).isInstanceOfSatisfying(DomainException.class,e->{assertThat(e.status).isEqualTo(HttpStatus.FORBIDDEN);assertThat(e.code).isEqualTo("CROP_BATCH_OWNERSHIP_REQUIRED");});}
@Test void cannotReviewTwice(){when(crop.batch(10)).thenReturn(Map.of("farmerId",7,"status","available","currentQuantity",BigDecimal.TEN));Map<?,?>created=(Map<?,?>)controller.create(Map.of("batchId",10,"rescuePointId",1)).getBody();long id=((Number)created.get("id")).longValue();auth(1);assertThat(controller.approve(id).get("status")).isEqualTo("APPROVED");assertThatThrownBy(()->controller.reject(id)).isInstanceOfSatisfying(DomainException.class,e->assertThat(e.code).isEqualTo("RESCUE_REGISTRATION_ALREADY_PROCESSED"));}private void auth(long id){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(String.valueOf(id),null));}}
